contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address vault,
        address asset,
        uint256 kink,
        uint256 slope0,
        uint256 slope1,
        uint256 maxMultiplier,
        uint256 minMultiplier,
        uint256 rateVal
    ) public {
        require(kink > 0 && kink < 1e27);

        bool slopesOk;
        try c.setSlopes(asset, IVaultAdapter.SlopeData(kink, slope0, slope1)) {
            slopesOk = true;
        } catch {
            slopesOk = false;
        }

        bool limitsOk;
        try c.setLimits(maxMultiplier, minMultiplier, rateVal) {
            limitsOk = true;
        } catch {
            limitsOk = false;
        }

        bool rateOk;
        uint256 observedRate;
        try c.rate(vault, asset) returns (uint256 r) {
            rateOk = true;
            observedRate = r;
        } catch {
            rateOk = false;
        }

        assert(slopesOk && (!limitsOk || rateOk));
    }
}

