contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address asset, address vault, uint256 kink) public {
        require(kink > 0 && kink < 1e27, "kink out of range");

        uint256 beforeLen = c.assets().length;
        uint256 beforeSupply = c.totalSupplies(asset);
        uint256 beforeBorrow = c.totalBorrows(asset);

        IVaultAdapter.SlopeData memory slopes = IVaultAdapter.SlopeData({kink: kink, slope0: 1e18, slope1: 1e18});
        c.setSlopes(asset, slopes);
        c.setLimits(1e27, 1e27, 0);

        uint256 rateOut = c.rate(vault, asset);

        assert(c.assets().length == beforeLen);
        assert(c.totalSupplies(asset) == beforeSupply);
        assert(c.totalBorrows(asset) == beforeBorrow);
        assert(rateOut == 0);
    }

    receive() external payable {}
}

